#include <stdio.h>
typedef struct Axis6W8bRow { unsigned int lane, frontier, shadow; int delta; } Axis6W8bRow;
typedef struct Axis6W8bAgg { unsigned int frontier[4], shadow[4]; int value[4]; } Axis6W8bAgg;
static unsigned int mix8b(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear8b(Axis6W8bAgg* a){ for(int i=0;i<4;++i){ a->frontier[i]=0u; a->shadow[i]=0u; a->value[i]=0; } }
static void absorb8b(Axis6W8bAgg* a,const Axis6W8bRow* r){ unsigned int lane=r->lane%4u; if(r->frontier<a->frontier[lane]) return; if(r->frontier>a->frontier[lane]){ a->frontier[lane]=r->frontier; a->shadow[lane]=r->shadow; a->value[lane]=r->delta; return; } if(r->shadow>a->shadow[lane]){ a->shadow[lane]=r->shadow; a->value[lane]=r->delta; } else if(r->shadow==a->shadow[lane]) a->value[lane]+=r->delta; }
static unsigned int sig8b(const Axis6W8bAgg* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<4u; ++lane){ h=mix8b(h,lane+1u); h=mix8b(h,a->frontier[lane]); h=mix8b(h,a->shadow[lane]); h=mix8b(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const Axis6W8bRow old_rows[]={{0u,3u,2u,4},{1u,2u,1u,5},{2u,4u,2u,6},{3u,3u,3u,7}}; const Axis6W8bRow new_rows[]={{0u,6u,5u,8},{1u,7u,4u,9},{2u,8u,6u,10},{3u,9u,5u,11}}; Axis6W8bAgg canonical,replayed; clear8b(&canonical); for(unsigned int i=0;i<4u;++i) absorb8b(&canonical,&new_rows[i]); clear8b(&replayed); absorb8b(&replayed,&old_rows[2]); absorb8b(&replayed,&new_rows[1]); absorb8b(&replayed,&old_rows[0]); absorb8b(&replayed,&new_rows[3]); absorb8b(&replayed,&new_rows[2]); absorb8b(&replayed,&old_rows[1]); absorb8b(&replayed,&new_rows[0]); absorb8b(&replayed,&old_rows[3]); { unsigned int sc=sig8b(&canonical), sr=sig8b(&replayed); printf("%u %u %u\n", sc, sr, (sc==sr)?1u:0u); } return 0; }
